import math

def check_n(n):
    if n < 2:
        return False

    # Check all k from 1 up to n-1
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            if (k**2 - 1) % n != 0:
                return False
    return True

# Test specific values from Candidate C
tests = [2, 3, 4, 6, 8, 12, 24]
results = {}
for n in tests:
    results[n] = check_n(n)

print("Verification of Candidate C members:")
for n, result in results.items():
    print(f"n={n}: {'WORKS' if result else 'FAILS'}")
